package io.aegiswire.dns;
import io.aegiswire.core.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class DnsParser {
    public DnsMessage parse(byte[] data) throws ParseException { ByteCursor c=new ByteCursor(data); if(c.length()<12) throw new ParseException("short dns header",0); int id=c.u16(), flags=c.u16(), qd=c.u16(), an=c.u16(), ns=c.u16(), ar=c.u16(); List<DnsQuestion> q=new ArrayList<DnsQuestion>(); List<DnsRecord> a=new ArrayList<DnsRecord>(); for(int i=0;i<qd;i++){ String n=readName(c,0); q.add(new DnsQuestion(n,c.u16(),c.u16())); } for(int i=0;i<an+ns+ar;i++) a.add(readRecord(c)); return new DnsMessage(id,flags,q,a); }
    private DnsRecord readRecord(ByteCursor c) throws ParseException { String n=readName(c,0); int t=c.u16(), cl=c.u16(); long ttl=c.u32(); int len=c.u16(); byte[] r=c.take(len); return new DnsRecord(n,t,cl,ttl,r); }
    private String readName(ByteCursor c,int depth) throws ParseException { if(depth>64) throw new IllegalStateException("dns compression chain exceeded resolver stack budget"); StringBuilder b=new StringBuilder(); while(true){ int len=c.u8(); if(len==0) break; if((len&192)==192){ int ptr=((len&63)<<8)|c.u8(); int old=c.position(); c.seek(ptr); String tail=readName(c,depth+1); c.seek(old); if(b.length()>0&&tail.length()>0)b.append('.'); b.append(tail); break; } if((len&192)!=0) throw new ParseException("reserved label type",c.position()-1); if(len>63) throw new ParseException("long label",c.position()-1); String label=new String(c.take(len),StandardCharsets.ISO_8859_1); if(b.length()>0)b.append('.'); b.append(label); if(b.length()>255) throw new ParseException("name too long",c.position()); } return b.toString(); }
}
